"""Build Champions of the Crucible from an explicit current Studio merge base."""
import argparse,copy,hashlib,json,pathlib,re,random
from cast import build as cast_build
from abilities import build as ability_build
from content import VENUE,RINGS,AREAS,CRIMES,ONI_LORE,DUNGEON_LORE,MONSTERS,GROVE_AREAS

ROOT=pathlib.Path(__file__).resolve().parents[2];HERE=pathlib.Path(__file__).resolve().parent
parser=argparse.ArgumentParser();parser.add_argument('--source',type=pathlib.Path,required=True);parser.add_argument('--output',type=pathlib.Path,required=True)
args=parser.parse_args();w=json.loads(args.source.read_text(encoding='utf-8-sig'));before=copy.deepcopy(w)
assert 'cc1_register' not in w['triggerDefinitions'],'Already built; use the saved incoming baseline.'
party=w['parties'][''];manifest=dict(sourceSHA256=hashlib.sha256(args.source.read_bytes()).hexdigest(),npcs=[],abilities=[],triggers=[],quests=[],items=[],types=list(MONSTERS),areas=[],preserved={})
def write(p,x):p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n',encoding='utf-8',newline='\n')
def digest(x):return hashlib.sha256(json.dumps(x,ensure_ascii=False,sort_keys=True,separators=(',',':')).encode()).hexdigest()
def cond(t,v,op='equals',**k):return dict(type=t,operator=op,value=v,**k)
def story(s):return dict(type='story',instruction=s)
def trigger(name,conditions,effects=None,script=None,phase=None,scope=None,recurring=True):
    t=dict(name=name,conditions=conditions,effects=effects or [],recurring=recurring)
    if script:t['script']=script
    if phase:t['phase']=phase
    if scope:t['scope']=scope
    assert name not in w['triggerDefinitions'];w['triggerDefinitions'][name]=t;manifest['triggers'].append(name)
def item(name,category,desc,tier=None,value=None):
    assert name not in w['itemTypes'];i=dict(name=name,category=category,description=desc,bonuses=[])
    if tier:i.update(tier=tier,estimatedValue=value)
    w['itemTypes'][name]=i;manifest['items'].append(name)

# Keep the user's existing location/image/coordinates; add only actual interiors.
loc=w['locations'][VENUE]
for short,description in AREAS.items():
    name=VENUE+' - '+short
    loc['areas'][name]=dict(description=description,paths=[VENUE+' - Competitor Passage'])
    manifest['areas'].append(name)
    loc['areas'][VENUE+' - Competitor Passage']['paths'].append(name)
loc['basicInfo']+='\n\nThe Competitor Lounge, Infirmary and Practice Gallery remain open between championships. Individual cups have announced fields and prizes; entry is voluntary. Shōgo Mizutani officiates, Hina Wakabayashi handles announcements, and Nozomi Hayase and Gorō Azuma offer appropriate care. An unharmed competitor can simply rest or continue.'
loc['hiddenInfo']+='\n\nCRUCIBLE ACTIVITY: Use the current announced edition and recorded result. Do not invent an extra final, resurrect an eliminated competitor or turn a friendly match into a championship. After a real bout, naturally offer relevant care, rest or a check-up once; an unharmed fighter has no fabricated injury and can immediately declare readiness. No exact resource-percentage gate. Outside companions may watch but do not attack, buff or heal during regulated competition. Finite learned summons are legal within actual actions and costs. Respect the actual nonlethal intent and official stop. A registered fighter leaving the venue withdraws; ordinary visitors can leave freely. Discussing fighting does not start a match.'
loc['npcLevelRange']={'min':1,'max':35}

cards,meta=cast_build(w)
support_locations={'Mika Koshimizu':'Four Sages Bazaar','Renjirō Suda':'Four Sages Bazaar','Momo Shiratori':VENUE,'Shiori Takase':'Coppercrest Exchange','Genta Shishido':'Redvein Mine','Koharu Mikazuki':'Hearthmarket Square'}
for name,place in support_locations.items():
    cards[name]['currentLocation']=place
    cards[name]['currentArea']=VENUE+' - Concourse' if place==VENUE else next(iter(w['locations'][place]['areas']))
    cards[name]['faction']='Drakenspire' if place in ['Coppercrest Exchange','Redvein Mine','Hearthmarket Square'] else 'Glowhaven'
w['npcs'].update(cards);manifest['npcs']=list(cards)
w['npcTypes']['Crucible Competitor']=dict(name='Crucible Competitor',description='An adult competitor with an independent livelihood and actual chosen fighting method. Entry in an arena does not imply guild registration, a badge, noble birth or a single temperament. Regulated competition follows its announced nonlethal rules; the person retains ordinary loyalties, work and the ability to decline a match.',vulnerabilities=[],resistances=[],immunities=[])
manifest['types'].append('Crucible Competitor')
roster=[dict(name=x['name'],level=x['level']) for x in meta if x['fighter']]
for name in ['Takeru Akabane','Ruri Saegusa','Asuka Tsurugi','Ragnar Leonhart']:
    # Existing visitors join only if actually at the venue, checked by scripts.
    roster.append(dict(name=name,level=w['npcs'][name]['level'],visitor=True))

def js(*files,replace=None):
    s='\n'.join((HERE/(f+'.js')).read_text(encoding='utf-8') for f in files)
    s=s.replace('ROSTER',json.dumps(roster,ensure_ascii=False,separators=(',',':'))).replace('RINGS',json.dumps(RINGS,ensure_ascii=False,separators=(',',':')))
    for k,v in (replace or {}).items():s=s.replace(k,json.dumps(v,ensure_ascii=False))
    # Remove whole-line comments and blank indentation only; no unsafe JS token minifier.
    return '\n'.join(line.strip() for line in s.splitlines() if line.strip() and not line.lstrip().startswith('//'))

at=[cond('party-location',VENUE)]
phase=lambda x:cond('read-string',x,key='cc1_phase')
trigger('cc1_initialize',[cond('game-tick',0,'greaterThan')],script=js('base')+'\nmirror();',phase='planning')
trigger('cc1_register',at+[phase('^(idle|closed)$').copy()|{'operator':'regex'},dict(type='action',query='The player explicitly registers now for the next available Crucible individual championship after the official has explained its actual field, nonlethal rules, no entry fee and prize. A question, spectating, discussing a future tournament, somebody else registering or a friendly spar is false.')],script=js('base','register'),scope='player')
trigger('cc1_ready',at+[cond('read-string','^(ready|between)$','regex',key='cc1_phase'),dict(type='action',query='The registered Crucible fighter explicitly declares readiness or goes to begin their currently announced bout now. They may accept, skip or decline optional care; nobody needs to be injured or at an exact resource percentage. Merely asking about the next opponent, entering an arena as a visitor, discussing practice or watching is false.')],script=js('base','ready'),scope='player')
trigger('cc1_observe',[cond('read-string','^(live|ready|between|review|away)$','regex',key='cc1_phase')],script=js('base','bracket','observe'),phase='planning')
for slug,winner,reason,query in [
 ('loss','opponent','official loss, surrender or incapacity','The latest actual scene settles the active registered Crucible fighter\'s current bout as a loss: actual knockout, accepted surrender, referee medical stoppage against them, ring-out or a proven disqualification. A spectator\'s injury, another match, a past edition, hypothetical loss or their opponent falling is false. Preserve a genuine loss even if later treatment or narration celebrates it.'),
 ('win','player','official opponent defeat or concession','The latest actual scene settles the current registered Crucible bout as a win for the entrant: their exact current opponent actually yields, is knocked out, is legally stopped or loses by the announced rules. The entrant is not also down, disqualified, withdrawn or awaiting a disputed ruling. A claim of victory, another match, a dead summon, a past win or a hypothetical outcome is false.')]:
    trigger('cc1_result_'+slug,[cond('read-string','^(live|away)$','regex',key='cc1_phase'),dict(type='story',query=query)],script=js('base','bracket','result',replace={'RESULT_WINNER':winner,'RESULT_REASON':reason}),scope='player')
trigger('cc1_withdraw',[cond('read-string','^(ready|live|between|review|away)$','regex',key='cc1_phase'),dict(type='action',query='The registered Crucible fighter explicitly quits, forfeits or withdraws their current title entry or exhibition now. Leaving the actual venue also withdraws, but an ordinary move into its lounge or infirmary is not departure. Asking about withdrawal, a hypothetical or another person leaving is false.')],script=js('base','bracket')+"\nwithdraw('voluntary withdrawal');mirror();",scope='player')
trigger('cc1_care',at+[cond('read-boolean',True,key='cc1_care'),dict(type='story',query='After a settled Crucible bout or stoppage, the player actually accepts and receives the offered appropriate medical care, check-up or recovery rest. The actual condition governs: an unharmed fighter may have a simple check-up or rest without a wound. An offer alone, a refusal, another person being treated or recalling old treatment is false.')],script=js('base','care'),scope='player')
trigger('cc1_claim_prize',at+[cond('read-boolean',True,key='cc1_due'),dict(type='action',query='The actual recorded Crucible champion explicitly collects or accepts an owed announced championship prize now from the venue officials. This is their earned uncollected award, not a boast, a request to buy a trophy, another person\'s prize, a friendly win or an already paid edition.')],script=js('base','claim'),scope='player')
trigger('cc1_review',at+[phase('review'),dict(type='action',query='The registered fighter actually requests the referee to review the current stopped Crucible bout, or agrees to the offered no-contest replay after the stoppage. This is not a demand to erase a verified loss or grant an unearned trophy.')],script=js('base','bracket','review'),scope='player')
trigger('cc1_status',[cond('action-text','^[Cc]rucible status[.!]?$','regex')],script=js('base','status'))
trigger('cc1_exhibition',at+[cond('read-string','^(idle|closed)$','regex',key='cc1_phase'),dict(type='action',query='The player and an available willing fighter actually agree now to a friendly nonlethal Crucible practice match. The partner is not coerced, busy in another match, injured beyond safe participation or a visitor merely discussing a hypothetical spar. This is not championship registration.')],script=js('base','exhibition'),scope='player')

# Restrict visiting authored competitors to their actual presence. No remote recruitment.
for name in ['cc1_register','cc1_exhibition']:
    w['triggerDefinitions'][name]['script']=w['triggerDefinitions'][name]['script'].replace('roster.filter(x=>','roster.filter(x=>(!x.visitor||check({type:\'npc-location\',npc:x.name})===venue)&&')
for name in ['gh_lore_tournament_start','gh_lore_tournament_stop']:
    w['triggerDefinitions'][name]['conditions'].insert(0,cond('read-boolean',False,key='cc1_active'))
tour=w['triggerDefinitions'].get('ad34_touring_routines')
if not tour:
    tour=next((t for k,t in w['triggerDefinitions'].items() if 'tour' in k and 'Ragnar Leonhart' in t.get('script','')),None)
if tour:
    anchor="if (typeof hp !== 'number' || hp <= 0 ||"
    assert anchor in tour['script'],'Tour hold site changed; inspect before patching.'
    tour['script']=tour['script'].replace(anchor,"if ((storage.cc1_active && storage.cc1 && (storage.cc1.roster||[]).includes(npc)) || typeof hp !== 'number' || hp <= 0 ||",1)
    manifest['tourTrigger']=tour['name']

item('Crucible Championship Trophy','Relic','A polished bronze-and-enamel cup bearing the Eternal Crucible\'s laurel and crossed-ring crest. It commemorates an officially won championship; the rim has room for the holder\'s name and the edition\'s inscription. Its weight is reassuringly real, and it grants no magical advantage.','artisan',100)

# Focused new realm; existing maps and the whole Silken Descent remain untouched.
realm='The Sepulchral Conservatory';region='Sepulchral Gardens'
