for i,(title,source,place,level,fee,premise,objective,brief) in enumerate(CRIMES):
    party['quests'][title]=dict(name=title,questSource=source,questLocation=place,detailType='detailed',status='hidden',questStatement=premise,mainObjective=objective,
      questDesignBrief=brief+' This is finite optional work. Establish the payer, method and compensation before acceptance. The quoted illicit fee is '+str(fee)+' marks; an alternative route needs its own real agreement. The completion effects supply no automatic illicit payout, so settle only the actual negotiated compensation once through supported ordinary item updates. Do not pay again when narrating a return. Do not expose private motives through a public offer.',
      completionCondition=dict(type='story',query='For the accepted undertaking "'+title+'", the actual agreed objective has been achieved: '+objective+' The chosen method and actual affected people matter. A promise, hypothetical, unrelated deed, merely hearing the offer or a refusal without accepted follow-through is false.'),onCompleteEffects=[],conclusive=True)
    manifest['quests'].append(title)
    trigger('cc1_crime_offer_'+str(i+1),[cond('party-location',place),cond('npc-in-scene',True,npc=source),cond('quest-status','hidden',questId=title),dict(type='story',query='The player has actually encountered the specific proposal "'+title+' from '+source+' and shown interest in its real terms. The actual scope and risk are understood. An arrival, a rumor, an unrelated request or a hidden motive the player has not discovered is false.')],effects=[dict(type='quest-init',operator='set',value=title)],recurring=False)

